    [CascadingParameter] private HttpContext HttpContext { get; set; } = default!;
    [SupplyParameterFromForm] private RegisterInput Input { get; set; } = new();

    private string? _error;

    private async Task DoRegister()
    {
        if (string.IsNullOrWhiteSpace(Input.Username) || string.IsNullOrWhiteSpace(Input.Password) ||
            string.IsNullOrWhiteSpace(Input.FullName) || string.IsNullOrWhiteSpace(Input.PhoneNumber) ||
            string.IsNullOrWhiteSpace(Input.Address))
        {
            _error = "Vui lòng nhập đầy đủ các trường bắt buộc!";
            return;
        }

        await using var db = await DbFactory.CreateDbContextAsync();
        var username = Input.Username.Trim();
        if (await db.Accounts.AnyAsync(a => a.Username == username))
        {
            _error = "Tên đăng nhập đã tồn tại. Vui lòng chọn tên khác!";
            return;
        }

        var account = new Account
        {
            Username = username,
            PasswordHash = Input.Password.Trim(),
            Role = "Customer",
            CreatedAt = DateTime.Now,
            IsActive = true
        };
        db.Accounts.Add(account);
        await db.SaveChangesAsync();

        db.Customers.Add(new Customer
        {
            AccountId = account.Id,
            FullName = Input.FullName.Trim(),
            PhoneNumber = Input.PhoneNumber.Trim(),
            Email = string.IsNullOrWhiteSpace(Input.Email) ? null : Input.Email.Trim(),
            Address = Input.Address.Trim(),
            CreatedAt = DateTime.Now
        });
        await db.SaveChangesAsync();

        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, account.Username),
            new(ClaimTypes.NameIdentifier, account.Id.ToString()),
            new(ClaimTypes.Role, account.Role)
        };
        var identity = new ClaimsIdentity(claims, CookieAuthenticationDefaults.AuthenticationScheme);
        await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme, new ClaimsPrincipal(identity));

        Nav.NavigateTo("/", forceLoad: true);
    }

    private sealed class RegisterInput
    {
        public string Username { get; set; } = "";
        public string Password { get; set; } = "";
        public string FullName { get; set; } = "";
        public string PhoneNumber { get; set; } = "";
        public string? Email { get; set; }
        public string Address { get; set; } = "";
    }

